import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Static Hermes Runtime","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/static-hermes-runtime/docs/index.md"},"headers":[],"relativePath":"tools/static-hermes-runtime/docs/index.md","filePath":"tools/static-hermes-runtime/docs/index.md","lastUpdated":1792029942000}`),a={name:`tools/static-hermes-runtime/docs/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="static-hermes-runtime" tabindex="-1">Static Hermes Runtime <a class="header-anchor" href="#static-hermes-runtime" aria-label="Permalink to “Static Hermes Runtime”">​</a></h1><p><code>@pumpkin-plugins/static-hermes-runtime</code> supplies the Static Hermes backend used by the plugin build tool. It compiles bundled JavaScript to Hermes bytecode by default, embeds the bytecode in a WebAssembly component, and links Hermes, the JSI shim, and generated Pumpkin/WASI bindings. Direct component builds can compile a TypeScript bundle with <code>--parse-ts</code>; Hermes marks that parser partial and unstable. Pumpkin runs the component through its WASI runtime. QuickJS remains available as an alternative engine.</p><p>For capability imports, host permissions, and WASI resource lifetimes, see the <a href="./wasi">WASI guide</a>. Runtime maintainers changing capability bundles or native adapters should use the <a href="./maintaining-wasi">WASI maintenance guide</a>.</p><p>Static Hermes uses the Hades garbage collector by default. Set <code>staticHermesGc</code> to <code>&quot;malloc&quot;</code> in a plugin&#39;s <code>pumpkinPlugin</code> configuration to use malloc-managed GC. Direct component builds accept <code>gcVariant: &quot;malloc&quot;</code> in <code>buildStaticHermesComponent</code> or <code>--gc-variant malloc</code> in the CLI. The repository&#39;s wasm32 WASI target has threads disabled, so Hades uses incremental collection instead of its concurrent collector. The incremental path is supported by the pinned Hermes source and may reduce collection pauses. The real-server engine comparison covers both collectors with the full and lean runtime profiles.</p><p>The Static Hermes adapter dispatches event, command, suggestion, task, custom AI-goal, and chunk-generation callbacks. AI-goal and chunk-generation callbacks receive Pumpkin resources that are disposed when the callback returns. AI-goal boolean callbacks return <code>false</code> when their handler throws; errors from void callbacks are logged. The adapter dispatches chunk-generation callbacks when the host invokes them. See the <a href="/pumpkin-plugins/guides/plugin-api/lifecycle-and-registration">lifecycle and registration guide</a> for callback details.</p><p>The pinned Pumpkin host <code>0.2.0+26.3-26.51</code> does not start custom WASM AI goals: its eligibility methods return <code>false</code>, so gameplay does not invoke those callbacks. See the <a href="https://github.com/Pumpkin-MC/Pumpkin/blob/0.2.0%2B26.3-26.51/crates/pumpkin/src/plugin/loader/wasm/wasm_host/wit/v0_1/mob.rs" target="_blank" rel="noreferrer">host implementation</a>.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};